import { styled as styledHexa } from '@hexa-ui/theme';

export const StyledRelatedAnalysisCard = styledHexa('div', {
  display: 'flex',
  flexDirection: 'row',
  alignItems: 'center',
  justifyContent: 'space-between',
  gap: '40px',
  width: '100%',
  padding: '24px 32px',
  backgroundColor: '#FFFFFF',
  border: '1px solid rgba(20, 20, 20, 0.12)',
  borderRadius: '16px',
  boxSizing: 'border-box',
});

export const StyledRelatedAnalysisContent = styledHexa('div', {
  display: 'flex',
  flexDirection: 'column',
  gap: '2px',
  flex: 1,
  minWidth: 0,
});

export const StyledRelatedAnalysisLabel = styledHexa('p', {
  margin: '0 0 14px',
  fontFamily: '$paragraph',
  fontSize: '11px',
  fontWeight: 600,
  lineHeight: '16px',
  letterSpacing: '0.08em',
  textTransform: 'uppercase',
  color: 'rgba(100, 116, 139, 1)',
});

export const StyledRelatedAnalysisTitle = styledHexa('h3', {
  margin: 0,
  fontFamily: '$heading',
  fontSize: '18px',
  fontWeight: 700,
  lineHeight: '24px',
  color: '#141414',
});

export const StyledRelatedAnalysisDescription = styledHexa('p', {
  margin: '10px 0 0',
  fontFamily: '$paragraph',
  fontSize: '14px',
  fontWeight: 400,
  lineHeight: '20px',
  color: 'rgba(75, 85, 99, 1)',
});

export const StyledRelatedAnalysisActions = styledHexa('div', {
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  justifyContent: 'center',
  gap: '8px',
  flexShrink: 0,
  width: '35%',
  padding: '0 16px',
});

export const StyledRelatedAnalysisCta = styledHexa('button', {
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  width: '100%',
  padding: '14px 32px',
  backgroundColor: '#141414',
  color: '#FFFFFF',
  border: 'none',
  borderRadius: '512px',
  fontFamily: '$paragraph',
  fontSize: '16px',
  fontWeight: 500,
  lineHeight: '24px',
  cursor: 'pointer',
  transition: 'background-color 0.15s ease-in-out',

  '&:hover': {
    backgroundColor: '#2E2E2E',
  },

  '&:active': {
    backgroundColor: '#404040',
  },
});

export const StyledRelatedAnalysisWarning = styledHexa('p', {
  margin: 0,
  fontFamily: '$paragraph',
  fontSize: '12px',
  fontWeight: 600,
  lineHeight: '16px',
  color: 'rgba(103, 102, 95, 1)',
  textAlign: 'center',
  width: '100%',
});
